"""End-to-end OPLS/2020 + CM1A assignment and GROMACS topology generation
(opls-ff-lite: no run-time QM fit)."""

from __future__ import annotations

import hashlib
import json
import re
from dataclasses import asdict, dataclass
from pathlib import Path

from rdkit import Chem

from .assignment import (
    DEFAULT_ATOMTYPE_ARCHIVE,
    AssignmentError,
    AssignmentResult,
    assign_molecule,
)
from .bonded import (
    STANDARD_RULES,
    BondedAssignment,
    assign_bonded_interactions,
)
from .amber import gaff2_display_types
from .gaff2_analogs import analog_gaff2_classes
from .gaff2_torsions import RULE_GAFF2_GENERAL
from .structure import apply_typing_aromaticity


TOPOLOGY_SCHEMA_VERSION = 1


@dataclass(frozen=True)
class GromacsTopologyResult:
    """Artifacts and in-memory assignments from a complete workflow run."""

    assignment: AssignmentResult
    bonded: BondedAssignment
    itp_path: Path
    gro_path: Path
    top_path: Path
    topology_json_path: Path


def _safe_identifier(value: str, fallback: str = "MOL") -> str:
    cleaned = re.sub(r"[^A-Za-z0-9_]+", "_", value.strip()).strip("_")
    if not cleaned:
        cleaned = fallback
    if cleaned[0].isdigit():
        cleaned = f"M_{cleaned}"
    return cleaned


def _topology_names(molecule: Chem.Mol, name: str) -> tuple[str, str, list[str]]:
    identifier = _safe_identifier(name)
    canonical_smiles = Chem.MolToSmiles(
        Chem.RemoveHs(molecule), canonical=True, isomericSmiles=True
    )
    digest = hashlib.sha256(f"{identifier}|{canonical_smiles}".encode()).hexdigest()[:8]
    molecule_type = f"MOL_{identifier}_{digest}"
    residue_name = re.sub(r"[^A-Za-z0-9]", "", identifier).upper()[:5] or "LIG"
    atom_types = [
        f"og{digest}_{index:03d}" for index in range(1, molecule.GetNumAtoms() + 1)
    ]
    return molecule_type, residue_name, atom_types


def _atom_name(element: str, index: int) -> str:
    return f"{element.upper()}{index:03d}"[-5:]


# OPLS/2020 class names use characters that are unusual in GROMACS
# bond_type names; every bonded term is written with explicit parameters, so
# the bond_type column is informational only.
_CLASS_CHARACTERS = {"$": "r", "!": "x", "=": "e", "#": "t", ":": "c", "+": "p", "%": "y"}


def _gromacs_class(opls_class: str) -> str:
    return "".join(_CLASS_CHARACTERS.get(c, c) for c in opls_class)


# Documented parameter choice (README, "Parameter choices"): tertiary amides
# keep the OPLS-AA type 239 (class N), not OPLS/2020's newer set 1035-1045.
TERTIARY_AMIDE_NOTE = (
    "; NOTE: tertiary amide N uses OPLS type 239 (class N) and the standard amide terms,"
    " not the newer OPLS/2020 tertiary-amide types 1035-1045 (class NM), by design."
)


def _charge_source(engine: str) -> str:
    return "CM1A from MOPAC AM1, opls_ff_lite.cm1a" if engine == "mopac" else engine


def _rule_comment(rule: str) -> str:
    """Trailing ITP comment for parameters not taken straight from the table."""
    return "" if rule in STANDARD_RULES else f" ; {rule}"


def _gaff2_type(atom) -> str | None:
    """GAFF2 type of an atom typed by the GAFF2 fallback, else None."""
    prefix = "amber:gaff2:"
    return atom.type_rule[len(prefix):] if atom.type_rule.startswith(prefix) else None


def _bond_type(atom) -> str:
    """bond_type column: the OPLS class, or the cosmetic opls_8NN name of a GAFF2 type."""
    gaff2 = _gaff2_type(atom)
    return gaff2_display_types()[gaff2] if gaff2 else _gromacs_class(atom.opls_class)


def _atom_comment(atom) -> str:
    if _gaff2_type(atom):
        return f" ; gaff2-lj {_bond_type(atom)}"
    return "" if atom.type_rule.startswith("smarts") else f" ; {atom.type_rule}"


def _gaff2_display_lines(assignment: AssignmentResult) -> list[str]:
    """Header lines naming the GAFF2 types behind the cosmetic opls_8NN labels."""
    used = sorted({_gaff2_type(atom) for atom in assignment.atoms} - {None},
                  key=lambda name: gaff2_display_types()[name])
    if not used:
        return []
    return [
        "; Their bond_type opls_8NN is a cosmetic label for the GAFF2 type (not an OPLS/2020",
        "; atom type; data/gaff2_display_types.json): "
        + ", ".join(f"{gaff2_display_types()[name]} = GAFF2 {name}" for name in used) + ".",
    ]


def _write_itp(
    path: Path,
    molecule: Chem.Mol,
    assignment: AssignmentResult,
    bonded: BondedAssignment,
    molecule_type: str,
    residue_name: str,
    atom_types: list[str],
) -> None:
    lines = [
        "; Generated by opls_ff_lite",
        "; OPLS/2020 atom types, classes and Lennard-Jones parameters"
        " (SMARTS typing; J. Phys. Chem. B 2024, doi:10.1021/acs.jpcb.3c06602)",
        f"; {assignment.charge_model} charges ({_charge_source(assignment.charge_engine)})",
        f"; Bonded parameters: {bonded.parameter_file}",
        *([f"; Missing bonded terms fitted on the fly: {bonded.qm_method}"]
          if bonded.qm_method else []),
        "; Atoms ending in '; borrowed:<rule>' use an existing OPLS-AA type borrowed",
        "; for chemistry that has no OPLS-AA type (atom-type archive); atoms ending in",
        "; '; analog:<rule>' have no OPLS rule and take the OPLS/2020 type analogous to",
        "; their GAFF2 type (src/opls_ff_lite/data/gaff2_opls_analogs.json); atoms ending in",
        "; '; gaff2-lj' have a GAFF2 type and GAFF2 Lennard-Jones parameters (no OPLS type).",
        *_gaff2_display_lines(assignment),
        "; Lines ending in '; <rule>' were not taken directly from the parameter table;",
        "; see the companion .topology.json for each term's rule and source line.",
        "; Torsions ending in '; gaff2-general X-B-C-X' use the GAFF2-derived general term",
        "; (src/opls_ff_lite/data/gaff2_general_torsions.par); '; parmchk2-<step> A-B-C-D penalty P'",
        "; were substituted as AmberTools parmchk2 does (table entry A-B-C-D, penalty P);",
        "; 'qm-check' marks terms flagged for a QM check. Bonds and angles ending in",
        "; '; qm-table' were recorded from earlier QM fits (src/opls_ff_lite/data/qm_bonded_terms.par),",
        "; '; gaff2' are gaff2.dat terms of the atoms' full GAFF2 types (data/gaff2_bonded.json).",
        "; Fallback when no table has the term (bonded_substitution.py): bonds ending in",
        "; '; [gaff2-]parmchk2-<step> A-B penalty P' or '; default-substitution A-B penalty P'",
        "; take b0 from the substitute bond A-B and the empirical (parmchk2 empbond) k;",
        "; '; empirical' bonds and angles use parmchk2's empirical rules (PARM_BLBA_GAFF2.DAT);",
        "; torsions ending in '; default-general X-B-C-X penalty P' use the general term with",
        "; P central atoms replaced by their default class; '; gaff2-dat-general X-b-c-X' the",
        "; gaff2.dat general term of the central atoms' full GAFF2 types; '; central-pair",
        "; A-B-C-D penalty P' the OPLS/2020 entry about the same central classes with the",
        "; closest end classes (P: 0 match, 1 same element, 2 other, 3 H/heavy per end);",
        "; '; zero-torsion' torsions have no parameter anywhere and are set to zero. Atoms ending in",
        "; '; collision-highest:<types>' matched several OPLS rules and no precedence entry:",
        "; the highest-numbered type was taken.",
        *(f"; WARNING: {warning}" for warning in bonded.warnings),
        *([TERTIARY_AMIDE_NOTE] if any(atom.opls_type == "opls_239" for atom in assignment.atoms)
          else []),
        "; Self-contained: needs only an OPLS [ defaults ] section"
        " (nbfunc 1, comb-rule 3, gen-pairs yes, fudgeLJ 0.5, fudgeQQ 0.5).",
        "",
        "[ atomtypes ]",
        "; name           bond_type  at.num      mass    charge ptype       sigma       epsilon",
    ]
    for zero_index, atom in enumerate(assignment.atoms):
        atomic_number = molecule.GetAtomWithIdx(zero_index).GetAtomicNum()
        sigma = 0.0 if atom.epsilon_kj_mol == 0.0 else atom.sigma_nm
        lines.append(
            f"{atom_types[zero_index]:<18s} {_bond_type(atom):<9s} {atomic_number:6d} "
            f"{atom.mass_u:10.5f} {0.0:9.4f} A "
            f"{sigma:12.7e} {atom.epsilon_kj_mol:12.7e}"
        )

    lines.extend(
        [
            "",
            "[ moleculetype ]",
            "; name                         nrexcl",
            f"{molecule_type:<32s} {bonded.nrexcl:d}",
            "",
            "[ atoms ]",
            "; nr  type                resnr residue atom  cgnr       charge        mass",
        ]
    )
    for atom, atom_type in zip(assignment.atoms, atom_types, strict=True):
        lines.append(
            f"{atom.index:5d} {atom_type:<19s} {1:5d} {residue_name:<5s} "
            f"{_atom_name(atom.element, atom.index):<5s} {1:5d} "
            f"{atom.final_charge_e:13.10f} {atom.mass_u:11.5f}"
            + _atom_comment(atom)
        )

    lines.extend(["", "[ bonds ]", "; ai    aj  funct       b0 (nm)       kb (kJ mol-1 nm-2)"])
    for value in bonded.bonds:
        lines.append(
            f"{value.atoms[0]:5d} {value.atoms[1]:5d} {1:5d} "
            f"{value.length_nm:13.7f} {value.force_constant_kj_mol_nm2:18.6f}"
            f"{_rule_comment(value.rule)}"
            + (f" {'-'.join(value.parameter_classes)} penalty {value.substitution_penalty:.1f}"
               if value.parameter_classes is not None else "")
        )

    lines.extend(["", "[ pairs ]", "; ai    aj  funct"])
    for value in bonded.pairs:
        lines.append(f"{value.atoms[0]:5d} {value.atoms[1]:5d} {value.function:5d}")

    lines.extend(
        [
            "",
            "[ angles ]",
            "; ai    aj    ak  funct   theta0 (deg)    ktheta (kJ mol-1 rad-2)",
        ]
    )
    for value in bonded.angles:
        lines.append(
            f"{value.atoms[0]:5d} {value.atoms[1]:5d} {value.atoms[2]:5d} {1:5d} "
            f"{value.angle_deg:14.7f} {value.force_constant_kj_mol_rad2:20.6f}"
            f"{_rule_comment(value.rule)}"
        )

    lines.extend(
        [
            "",
            "[ dihedrals ]",
            "; proper Ryckaert-Bellemans torsions",
            "; ai    aj    ak    al  funct          C0          C1          C2          C3          C4          C5",
        ]
    )
    for value in bonded.proper_torsions:
        atoms = " ".join(f"{index:5d}" for index in value.atoms)
        coefficients = " ".join(
            f"{coefficient:11.6f}" for coefficient in value.coefficients_kj_mol
        )
        comment = _rule_comment(value.rule)
        if value.substitution_penalty is not None:
            comment += (f" {'-'.join(value.parameter_classes)}"
                        f" penalty {value.substitution_penalty:.1f}")
        elif value.rule == RULE_GAFF2_GENERAL:
            comment += f" {'-'.join(value.parameter_classes)}"
        if value.qm_check:
            comment += " qm-check" if comment else " ; qm-check"
        lines.append(f"{atoms} {3:5d} {coefficients}{comment}")

    if bonded.improper_torsions:
        lines.extend(
            [
                "",
                "[ dihedrals ]",
                "; periodic improper torsions",
                "; ai    aj    ak    al  funct  phase (deg)      k (kJ mol-1)  multiplicity",
            ]
        )
        for value in bonded.improper_torsions:
            atoms = " ".join(f"{index:5d}" for index in value.atoms)
            lines.append(
                f"{atoms} {4:5d} {value.phase_deg:12.6f} "
                f"{value.force_constant_kj_mol:17.6f} {value.multiplicity:5d}"
            )

    path.write_text("\n".join(lines) + "\n")


def _write_gro(
    path: Path,
    molecule: Chem.Mol,
    name: str,
    residue_name: str,
    padding_nm: float,
) -> None:
    if padding_nm < 0:
        raise AssignmentError("GROMACS box padding cannot be negative")
    conformer = molecule.GetConformer()
    coordinates = [
        [
            conformer.GetAtomPosition(index).x / 10.0,
            conformer.GetAtomPosition(index).y / 10.0,
            conformer.GetAtomPosition(index).z / 10.0,
        ]
        for index in range(molecule.GetNumAtoms())
    ]
    minima = [min(point[axis] for point in coordinates) for axis in range(3)]
    maxima = [max(point[axis] for point in coordinates) for axis in range(3)]
    shifted = [
        [point[axis] - minima[axis] + padding_nm for axis in range(3)]
        for point in coordinates
    ]
    box = [maxima[axis] - minima[axis] + 2.0 * padding_nm for axis in range(3)]

    lines = [f"{name} generated by opls_ff_lite", f"{molecule.GetNumAtoms():5d}"]
    for index, (atom, coordinate) in enumerate(
        zip(molecule.GetAtoms(), shifted, strict=True), start=1
    ):
        lines.append(
            f"{1:5d}{residue_name:<5.5s}{_atom_name(atom.GetSymbol(), index):>5.5s}"
            f"{index % 100000:5d}{coordinate[0]:8.3f}{coordinate[1]:8.3f}{coordinate[2]:8.3f}"
        )
    lines.append("".join(f"{length:10.5f}" for length in box))
    path.write_text("\n".join(lines) + "\n")


OPLS_DEFAULTS = [
    "[ defaults ]",
    "; nbfunc  comb-rule  gen-pairs  fudgeLJ  fudgeQQ",
    "1         3          yes        0.5      0.5",
    "",
]


def _write_top(path: Path, itp_name: str, molecule_type: str, name: str) -> None:
    path.write_text(
        "\n".join(
            [
                "; Generated by opls_ff_lite",
                *OPLS_DEFAULTS,
                f'#include "{itp_name}"',
                "",
                "[ system ]",
                name,
                "",
                "[ molecules ]",
                "; molecule                     count",
                f"{molecule_type:<32s} 1",
                "",
            ]
        )
    )


def _write_topology_json(
    path: Path,
    assignment: AssignmentResult,
    bonded: BondedAssignment,
    molecule_type: str,
    residue_name: str,
    atom_types: list[str],
    itp_path: Path,
    gro_path: Path,
    top_path: Path,
) -> None:
    payload = {
        "schema_version": TOPOLOGY_SCHEMA_VERSION,
        "name": assignment.name,
        "molecule_type": molecule_type,
        "residue_name": residue_name,
        "charge_model": assignment.charge_model,
        "parameter_file": str(bonded.parameter_file),
        "qm_method": bonded.qm_method,
        "borrowed_atoms": {
            str(atom.index): atom.type_rule
            for atom in assignment.atoms
            if not atom.type_rule.startswith("smarts")
        },
        "bonded_rule_counts": bonded.rule_counts(),
        "bonded_warnings": list(bonded.warnings),
        "defaults": {
            "nrexcl": bonded.nrexcl,
            "fudge_lj": bonded.fudge_lj,
            "fudge_qq": bonded.fudge_qq,
        },
        "files": {
            "itp": str(itp_path),
            "gro": str(gro_path),
            "top": str(top_path),
            "assignment": str(assignment.json_path),
        },
        "atom_types": atom_types,
        "bonds": [asdict(value) for value in bonded.bonds],
        "angles": [asdict(value) for value in bonded.angles],
        "proper_torsions": [asdict(value) for value in bonded.proper_torsions],
        "improper_torsions": [asdict(value) for value in bonded.improper_torsions],
        "pairs": [asdict(value) for value in bonded.pairs],
    }
    path.write_text(json.dumps(payload, indent=2) + "\n")


def _write_outputs(
    molecule: Chem.Mol,
    assignment: AssignmentResult,
    bonded: BondedAssignment,
    output_directory: Path,
    name: str,
    box_padding_nm: float,
) -> GromacsTopologyResult:
    molecule_type, residue_name, atom_types = _topology_names(molecule, name)
    stem = _safe_identifier(name).lower()
    itp_path = output_directory / f"{stem}.itp"
    gro_path = output_directory / f"{stem}.gro"
    top_path = output_directory / f"{stem}.top"
    topology_json_path = output_directory / f"{stem}.topology.json"

    _write_itp(
        itp_path,
        molecule,
        assignment,
        bonded,
        molecule_type,
        residue_name,
        atom_types,
    )
    _write_gro(gro_path, molecule, name, residue_name, box_padding_nm)
    _write_top(top_path, itp_path.name, molecule_type, name)
    _write_topology_json(
        topology_json_path,
        assignment,
        bonded,
        molecule_type,
        residue_name,
        atom_types,
        itp_path,
        gro_path,
        top_path,
    )
    return GromacsTopologyResult(
        assignment=assignment,
        bonded=bonded,
        itp_path=itp_path,
        gro_path=gro_path,
        top_path=top_path,
        topology_json_path=topology_json_path,
    )


def generate_gromacs_topology(
    molecule: Chem.Mol,
    output_directory: str | Path,
    *,
    name: str | None = None,
    charge_model: str = "auto",
    atomtype_archive: str | Path | None = DEFAULT_ATOMTYPE_ARCHIVE,
    amber_fallback: bool = True,
    torsion_substitution: bool = True,
    qm_bonded_table: bool = True,
    timeout_seconds: int = 300,
    box_padding_nm: float = 1.0,
) -> GromacsTopologyResult:
    """Run atom typing, charge assignment, bonded assignment, and ITP writing.

    Bonded terms come first from the OPLS/2020 table; missing terms take the
    lookups and fallbacks of ``bonded.py``, so every term gets a value
    (torsions with no parameter anywhere: zero). ``torsion_substitution``
    (default on) enables the torsion lookups after the table (GAFF2-derived
    general terms, parmchk2 substitution, fallback); off, a missing torsion
    is an error. ``qm_bonded_table`` (default on) fills bonds and angles the
    table lacks from the recorded values of earlier QM fits of the full
    opls-ff-gen (``qm_bonded.py``, ``data/qm_bonded_terms.par``; no QM is run).
    Charged molecules: ``charge_model="auto"`` gives ions unscaled CM1A and
    neutral molecules (zwitterions included) 1.14*CM1A-LBCC.
    """
    molecule = apply_typing_aromaticity(Chem.Mol(molecule))
    if name is None:
        name = molecule.GetProp("_Name") if molecule.HasProp("_Name") else "molecule"
    output_directory = Path(output_directory).resolve()
    output_directory.mkdir(parents=True, exist_ok=True)

    assignment = assign_molecule(
        molecule,
        output_directory,
        name=name,
        charge_model=charge_model,
        timeout_seconds=timeout_seconds,
        atomtype_archive=atomtype_archive,
        amber_fallback=amber_fallback,
    )
    bonded = assign_bonded_interactions(
        molecule,
        [atom.opls_class for atom in assignment.atoms],
        torsion_substitution=torsion_substitution,
        qm_bonded_table=qm_bonded_table,
        gaff2_classes=analog_gaff2_classes(molecule, [atom.type_rule for atom in assignment.atoms]),
    )
    return _write_outputs(molecule, assignment, bonded, output_directory, name, box_padding_nm)
